mapper.select:
SELECT id, api_code, batch_no, file_name, file_path,
       total_count, success_count, deal_status,
       is_del, create_time, update_time, sync_record_id,
       quick_deal_status,db_deal_status
FROM b_marketing_tcyr_sync_file
WHERE api_code=#{apiCode}
  and quick_deal_status=#{quickDealStatus}
  and db_deal_status=#{dbDealStatus}
  and is_del=1
    LIMIT 1

mapper.update:
UPDATE
    b_marketing_tcyr_sync_file
SET quick_deal_status = #{quickDealStatus}
WHERE id=#{id}

UPDATE
    b_marketing_tcyr_sync_file
SET db_deal_status = #{dbDealStatus}
WHERE id=#{id}

UPDATE
    b_marketing_tcyr_sync_file
SET success_count = success_count +#{addSuccessCount}
where id = #{syncFileId}

UPDATE
    b_marketing_tcyr_sync_file
SET quick_deal_status = #{quickDealStatus},success_count = success_count +#{addSuccessCount}
where id = #{syncFileId}
